SINA_SMART["hemato1-haematopoiesis"] = {"lecture":"hemato1-haematopoiesis","title":"Haematopoiesis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"hemato1-haematopoiesis:e0","text":"Haematopoiesis: all blood cells from the HSC; 10¹¹-10¹² cells/day.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e1","text":"Life spans: RBC 120 d, platelets 7-10 d, WBC days.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e2","text":"Continuous, regulated, adaptive (altitude, infection).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e3","text":"Sites: yolk sac → AGM → liver (+ spleen) → bone marrow (axial skeleton).","topic":"Sites","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e4","text":"Extramedullary haematopoiesis in thalassaemia, myelofibrosis → hepatosplenomegaly.","topic":"Sites","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e5","text":"HSC: multipotent, self-renewing, low mitosis, CD-identified.","topic":"Compartments","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e6","text":"Progenitors: CMP, CLP; committed, mitotic, not recognisable.","topic":"Compartments","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e7","text":"Precursors (blasts): recognisable, one lineage, no self-renewal.","topic":"Compartments","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e8","text":"Early factors: SCF, IL-3, GM-CSF, IL-7; lineage: EPO, TPO, G-CSF, M-CSF.","topic":"Regulation and exploration","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"hemato1-haematopoiesis:e9","text":"Exploration: CBC, blood film, marrow smear, marrow biopsy; flow cytometry.","topic":"Regulation and exploration","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"58thyz":"a","8ab8wq":"a","j30v42":"a","sg33il":"a","w1si9c":"a","1lrdzga":"a","3if2qq":"a","wx28zw":"a","1g0n977":"a","1fn3m2z":"a","1789sdf":"a","36mquv":"a","jwtjkv":"a","1rtwbtn":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"hemato1-haematopoiesis:e0":{"s":0,"u":["Haematopoiesis: all blood cells from the HSC; 10¹¹-10¹² cells/day.","Haematopoiesis is the process that produces all blood cells from the haematopoietic stem cell (HSC) .","It is continuous from embryo to death, regulated and adaptive (more red cells at altitude, more white cells in infection, via cytokines and growth factors), and the most regenerative tissue : 10¹¹-10¹² cells per day (red cells about 200 × 10⁹ a day, 2 million per second)."],"dp":[]},"hemato1-haematopoiesis:e1":{"s":0,"u":["Life spans: RBC 120 d, platelets 7-10 d, WBC days.","It is vital because mature cells live briefly ( red cells 120 days , platelets 7-10 days , white cells a few days in blood), cannot divide (except monocytes and lymphocytes), and their numbers must stay constant."],"dp":[]},"hemato1-haematopoiesis:e2":{"s":0,"u":["Continuous, regulated, adaptive (altitude, infection).","It is continuous from embryo to death, regulated and adaptive (more red cells at altitude, more white cells in infection, via cytokines and growth factors), and the most regenerative tissue : 10¹¹-10¹² cells per day (red cells about 200 × 10⁹ a day, 2 million per second)."],"dp":[]},"hemato1-haematopoiesis:e3":{"s":1,"u":["Sites: yolk sac → AGM → liver (+ spleen) → bone marrow (axial skeleton).","After birth : bone marrow , progressively confined to the axial skeleton .","Late fetus : liver, spleen, placenta, then bone marrow."],"dp":[]},"hemato1-haematopoiesis:e4":{"s":1,"u":["Extramedullary haematopoiesis in thalassaemia, myelofibrosis → hepatosplenomegaly.","In marrow failure (thalassaemia, myelofibrosis) haematopoiesis can return to the spleen and liver (extramedullary haematopoiesis), causing hepatosplenomegaly."],"dp":[]},"hemato1-haematopoiesis:e5":{"s":2,"u":["HSC: multipotent, self-renewing, low mitosis, CD-identified.","HSCs : multipotent , self-renewing , low mitotic activity, not morphologically identifiable (look like large lymphocytes)."],"dp":[]},"hemato1-haematopoiesis:e6":{"s":2,"u":["Progenitors: CMP, CLP; committed, mitotic, not recognisable.","Progenitors : lineage-committed, highly mitotic, less self-renewal, not identifiable: the common myeloid progenitor (CMP) gives the megakaryocyte-erythroid progenitor (→ BFU-E/CFU-E → red cells; CFU-Mk → platelets), the granulocyte-macrophage progenitor (CFU-GM → neutrophils, monocytes) and CFU-Eo and CFU-Baso; the common lymphoid progenitor (CLP) gives B, T and NK precursors."],"dp":[]},"hemato1-haematopoiesis:e7":{"s":2,"u":["Precursors (blasts): recognisable, one lineage, no self-renewal.","Precursors (blasts) : morphologically identifiable, unilineage, highly mitotic, no self-renewal: proerythroblast, myeloblast, megakaryoblast, lymphoblast, monoblast."],"dp":[]},"hemato1-haematopoiesis:e8":{"s":3,"u":["Early factors: SCF, IL-3, GM-CSF, IL-7; lineage: EPO, TPO, G-CSF, M-CSF.","Lineage-specific: EPO (erythropoietin: red cells), TPO (thrombopoietin: platelets), G-CSF (neutrophils), M-CSF (monocytes).","Early, multilineage: SCF (stem cell factor), IL-3 , GM-CSF , IL-7 (lymphoid)."],"dp":[{"h":"Why G-CSF is given after chemotherapy","t":"Chemotherapy kills dividing cells, including marrow progenitors, so neutrophils (which live only days) fall first, exposing patients to severe infections. Injecting G-CSF, the neutrophil-specific growth factor, pushes the surviving progenitors to proliferate and mature, shortening the period of neutropenia. It also mobilises stem cells into the blood for collection before transplantation. Source: the lecture's growth factor slides."}]},"hemato1-haematopoiesis:e9":{"s":3,"u":["Exploration: CBC, blood film, marrow smear, marrow biopsy; flow cytometry.","Exploration: complete blood count (automated, simple), blood film , bone marrow smear (aspirate) and bone marrow biopsy ."],"dp":[]}},"meta":{"58thyz":{"a":"recall","vg":"hemato1-haematopoiesis:e0/recall/1"},"8ab8wq":{"a":"recall","vg":"hemato1-haematopoiesis:e1/recall/1"},"j30v42":{"a":"recall","vg":"hemato1-haematopoiesis:e4/recall/1"},"sg33il":{"a":"recall","vg":"hemato1-haematopoiesis:e3/recall/1"},"w1si9c":{"a":"recall","vg":"hemato1-haematopoiesis:e3/recall/2"},"1lrdzga":{"a":"recall","vg":"hemato1-haematopoiesis:e4/recall/2"},"3if2qq":{"a":"recall","vg":"hemato1-haematopoiesis:e7/recall/1"},"wx28zw":{"a":"recall","vg":"hemato1-haematopoiesis:e6/recall/1"},"1g0n977":{"a":"recall","vg":"hemato1-haematopoiesis:e7/recall/2"},"1fn3m2z":{"a":"recall","vg":"hemato1-haematopoiesis:e6/recall/2"},"1789sdf":{"a":"recall","vg":"hemato1-haematopoiesis:e0/recall/2"},"36mquv":{"a":"recall","vg":"hemato1-haematopoiesis:e8/recall/1"},"jwtjkv":{"a":"recall","vg":"hemato1-haematopoiesis:e8/recall/2"},"1rtwbtn":{"a":"recall","vg":"hemato1-haematopoiesis:e9/recall/1"}},"explRev":"564624d79fdb"};
